/* ─── MASTER / COMBO ────────────────────────────────────── */
const MASTER_KEY='master';
const LEVELS=['project','system','typeloc','loc','sub','equip','serial'];
const PROP={project:'project',system:'system',typeloc:'typeLocation',loc:'locName',sub:'subName',equip:'equipment',serial:'serial'};
const LABEL={project:'โครงการ',system:'ระบบ',typeloc:'ประเภทสถานที่',loc:'สถานที่',sub:'สถานที่ย่อย',equip:'อุปกรณ์',serial:'Serial Number'};
let master=[],entries=[],editingId=null,imgMain='',imgSticker='',img3='',img4='';
const sel={project:'',system:'',loc:'',sub:'',equip:'',serial:''};
const combos={};
const INSP_SEED=['สมชาย ใจดี','สมหญิง รักงาน'];

async function loadAll(){const m=await sGet(MASTER_KEY);if(m){try{master=JSON.parse(m);}catch(e){master=[];}}if(!master.length)master=seed();buildCombos();buildInspectorCombo();refreshDerived();renderMaster();renderSaved();updateStats();}
function seed(){return [{id:uid(),project:'รถไฟฟ้าสายสีทอง',system:'ไฟฟ้า',locName:'สถานีกรุงธนบุรี',subName:'ห้องไฟฟ้า',equipment:'ตู้ MDB',brand:'Siemens',model:'SIVACON S8',asset:'GL-EQ-001',serial:'SN-2024-00123'},{id:uid(),project:'รถไฟฟ้าสายสีทอง',system:'ไฟฟ้า',locName:'สถานีกรุงธนบุรี',subName:'ห้องไฟฟ้า',equipment:'Inverter',brand:'ABB',model:'ACS580',asset:'GL-EQ-002',serial:'SN-2024-00124'}];}

async function sGet(k){try{return localStorage.getItem(k);}catch(e){return null;}}
async function sSet(k,v){try{localStorage.setItem(k,v);}catch(e){console.warn(e);}}

function optionsFor(level){
  const idx=LEVELS.indexOf(level);let rows=master;
  const role=AUTH.user?.role||'';const userProjs=(AUTH.user?.project||'').split(',').map(p=>p.trim()).filter(Boolean);
  if((role==='leader'||role==='inspector')&&userProjs.length>0)rows=rows.filter(r=>userProjs.includes(r.project));
  for(let i=0;i<idx;i++){const lv=LEVELS[i];if(sel[lv])rows=rows.filter(r=>String(r[PROP[lv]]||'')===sel[lv]);}
  if(level==='serial'){const brand=($('#inpBrand')&&$('#inpBrand').value||'').trim();if(brand)rows=rows.filter(r=>String(r.brand||'')===brand);return uniq(rows.map(r=>String(r.serial||'')).filter(Boolean)).sort((a,b)=>a.localeCompare(b,'th'));}
  return uniq(rows.map(r=>String(r[PROP[level]]||''))).sort((a,b)=>a.localeCompare(b,'th'));
}
function buildCombos(){
  LEVELS.forEach(level=>{
    const el=document.querySelector(`.combo[data-level="${level}"]`);
    el.innerHTML=`<div class="combo-ctl"><input class="combo-input" placeholder="พิมพ์หรือเลือก${LABEL[level]}..." autocomplete="off"><span class="combo-clear">&times;</span><span class="combo-caret">▾</span></div><div class="combo-list"></div>`;
    const input=el.querySelector('.combo-input'),list=el.querySelector('.combo-list'),clear=el.querySelector('.combo-clear');
    combos[level]={el,input,list};let active=-1;
    const isDisabled=()=>el.classList.contains('disabled');
    function render(filter){let opts=optionsFor(level);const f=(filter||'').trim().toLowerCase();if(f)opts=opts.filter(o=>o.toLowerCase().includes(f));active=-1;let html=opts.map(o=>`<div class="combo-opt" data-v="${escAttr(o)}">${esc(o)}</div>`).join('');const exact=optionsFor(level).some(o=>o.toLowerCase()===f);if(f&&!exact)html+=`<div class="combo-new" data-new="${escAttr(filter.trim())}">+ ใช้ "${esc(filter.trim())}" (ใหม่)</div>`;if(!html)html=`<div class="combo-empty">ไม่มีตัวเลือก</div>`;list.innerHTML=html;list.querySelectorAll('.combo-opt').forEach(o=>o.addEventListener('mousedown',e=>{e.preventDefault();choose(level,o.dataset.v);}));const nw=list.querySelector('.combo-new');if(nw)nw.addEventListener('mousedown',e=>{e.preventDefault();choose(level,nw.dataset.new);});}
    function open(){if(isDisabled())return;el.classList.add('open');render(input.value);}
    function close(){el.classList.remove('open');}
    input.addEventListener('focus',open);input.addEventListener('click',open);
    input.addEventListener('input',()=>{el.classList.add('open');render(input.value);});
    input.addEventListener('keydown',e=>{const items=list.querySelectorAll('.combo-opt,.combo-new');if(e.key==='ArrowDown'){e.preventDefault();active=Math.min(active+1,items.length-1);}else if(e.key==='ArrowUp'){e.preventDefault();active=Math.max(active-1,0);}else if(e.key==='Enter'){e.preventDefault();if(active>=0){const it=items[active];choose(level,it.dataset.v||it.dataset.new);}else if(input.value.trim())choose(level,input.value.trim());return;}else if(e.key==='Escape'){close();return;}items.forEach((it,i)=>it.classList.toggle('active',i===active));if(active>=0)items[active].scrollIntoView({block:'nearest'});});
    input.addEventListener('blur',()=>setTimeout(()=>{close();const v=input.value.trim();if(v!==sel[level])choose(level,v);},150));
    clear.addEventListener('mousedown',e=>{e.preventDefault();choose(level,'');});
  });
  setDisabledStates();
}
function choose(level,val){val=String(val||'').trim();if(sel[level]===val){combos[level].input.value=val;combos[level].el.classList.toggle('has-val',!!val);combos[level].el.classList.remove('open');return;}sel[level]=val;combos[level].input.value=val;combos[level].el.classList.toggle('has-val',!!val);combos[level].el.classList.remove('open');const idx=LEVELS.indexOf(level);for(let i=idx+1;i<LEVELS.length;i++){const lv=LEVELS[i];sel[lv]='';if(combos[lv]){combos[lv].input.value='';combos[lv].el.classList.remove('has-val');}}setDisabledStates();updateBrandModel();}
function setDisabledStates(){LEVELS.forEach((lv,i)=>{const parentOk=i===0?true:!!sel[LEVELS[i-1]];const c=combos[lv];if(!c)return;if(parentOk){c.el.classList.remove('disabled');c.input.disabled=false;c.input.placeholder=`พิมพ์หรือเลือก${LABEL[lv]}...`;}else{c.el.classList.add('disabled');c.input.disabled=true;c.input.placeholder=`เลือก${LABEL[LEVELS[i-1]]}ก่อน`;}});if(combos.serial)refreshSerialCombo();}
function updateBrandModel(){let rows=master;['project','system','loc','sub','equip','serial'].forEach(lv=>{if(sel[lv])rows=rows.filter(r=>String(r[PROP[lv]]||'')===sel[lv]);});const brands=uniq(rows.map(r=>r.brand)),models=uniq(rows.map(r=>r.model)),assets=uniq(rows.map(r=>r.asset));setBM('bmBrand','inpBrand',brands);setBM('bmModel','inpModel',models);if(assets.length===1&&!$('#inpAsset').value)$('#inpAsset').value=assets[0];}
function refreshSerialCombo(){if(!combos.serial)return;const valid=optionsFor('serial');if(sel.serial&&!valid.includes(sel.serial)){sel.serial='';combos.serial.input.value='';combos.serial.el.classList.remove('has-val');}const ph=sel.equip?(valid.length?`เลือก Serial (${valid.length} รายการ)`:'ไม่มี Serial ใน master'):'เลือกอุปกรณ์ก่อน';if(combos.serial.input)combos.serial.input.placeholder=ph;}
function setBM(boxId,inpId,vals){const box=$('#'+boxId),inp=$('#'+inpId);if(sel.equip&&vals.length===1){box.classList.remove('empty');box.innerHTML=`<input id="${inpId}" style="display:none">`+esc(vals[0]);$('#'+inpId).value=vals[0];}else if(sel.equip){box.classList.remove('empty');box.innerHTML=`<input id="${inpId}" placeholder="กรอกเอง" value="${escAttr(vals[0]||'')}">`;}else{box.classList.add('empty');box.innerHTML=`<input id="${inpId}" style="display:none">`+(box.dataset.empty||'—');$('#'+inpId).value='';}}
function refreshDerived(){$('#masterPill').textContent=master.length;}

// แทน <input list="..."> ของ browser ด้วย combo style เดียวกับหน้า "เพิ่มรายการ" (ไม่มี "+ ใช้...ใหม่" — พิมพ์เองได้ตรงๆอยู่แล้ว)
// ใช้ inputId เดิม (ย้าย element เดิมเข้า wrapper) เพื่อให้โค้ดเดิมที่อ่าน $('#id').value ไม่ต้องแก้อะไรเลย
function upgradeToCombo(inputIdOrEl,getOptionsFn){
  const inp=typeof inputIdOrEl==='string'?document.getElementById(inputIdOrEl):inputIdOrEl;
  if(!inp||inp.dataset.comboUpgraded)return;
  inp.dataset.comboUpgraded='1';
  inp.removeAttribute('list');
  inp.classList.add('combo-input');
  inp.setAttribute('autocomplete','off');
  const wrap=document.createElement('div');wrap.className='combo';
  const ctl=document.createElement('div');ctl.className='combo-ctl';
  inp.parentNode.insertBefore(wrap,inp);
  ctl.appendChild(inp);wrap.appendChild(ctl);
  const clearBtn=document.createElement('span');clearBtn.className='combo-clear';clearBtn.innerHTML='&times;';ctl.appendChild(clearBtn);
  const caret=document.createElement('span');caret.className='combo-caret';caret.textContent='▾';ctl.appendChild(caret);
  const list=document.createElement('div');list.className='combo-list';wrap.appendChild(list);
  let active=-1;
  function render(filter){
    let opts=getOptionsFn();
    const f=(filter||'').trim().toLowerCase();
    if(f)opts=opts.filter(o=>String(o).toLowerCase().includes(f));
    active=-1;
    let html=opts.map(o=>`<div class="combo-opt" data-v="${escAttr(o)}">${esc(o)}</div>`).join('');
    if(!html)html=`<div class="combo-empty">ไม่มีตัวเลือก</div>`;
    list.innerHTML=html;
    list.querySelectorAll('.combo-opt').forEach(o=>o.addEventListener('mousedown',e=>{e.preventDefault();pick(o.dataset.v);}));
  }
  function pick(v){inp.value=v;wrap.classList.toggle('has-val',!!v);wrap.classList.remove('open');inp.dispatchEvent(new Event('input',{bubbles:true}));inp.dispatchEvent(new Event('change',{bubbles:true}));}
  function open(){wrap.classList.add('open');render(inp.value);}
  inp.addEventListener('focus',open);
  inp.addEventListener('click',open);
  inp.addEventListener('input',()=>{wrap.classList.add('open');wrap.classList.toggle('has-val',!!inp.value);render(inp.value);});
  inp.addEventListener('keydown',e=>{
    const items=list.querySelectorAll('.combo-opt');
    if(e.key==='ArrowDown'){e.preventDefault();active=Math.min(active+1,items.length-1);}
    else if(e.key==='ArrowUp'){e.preventDefault();active=Math.max(active-1,0);}
    else if(e.key==='Enter'){if(active>=0){e.preventDefault();pick(items[active].dataset.v);}return;}
    else if(e.key==='Escape'){wrap.classList.remove('open');return;}
    items.forEach((it,i)=>it.classList.toggle('active',i===active));
    if(active>=0)items[active].scrollIntoView({block:'nearest'});
  });
  inp.addEventListener('blur',()=>setTimeout(()=>wrap.classList.remove('open'),150));
  clearBtn.addEventListener('mousedown',e=>{e.preventDefault();pick('');});
  wrap.classList.toggle('has-val',!!inp.value);
}
// คืนค่าตัวเลือกปัจจุบันจาก <datalist> (อ่านสดทุกครั้ง เผื่อมีการเติม option เพิ่มทีหลัง เช่นตอน loadReportPresets/loadReportInfo)
function dlOptions(datalistId){return ()=>{const dl=document.getElementById(datalistId);return dl?Array.from(dl.options).map(o=>o.value).filter(Boolean):[];};}
// sync class "has-val" เวลามีโค้ดอื่นไป set .value ตรงๆ (ไม่ผ่าน pick()) เช่นตอนเปิด dialog แล้วเติมค่าเริ่มต้น
function syncComboVal(inputId){const inp=document.getElementById(inputId);const wrap=inp&&inp.closest('.combo');if(wrap)wrap.classList.toggle('has-val',!!inp.value);}

function buildInspectorCombo(){const el=$('#inspCombo');if(!el)return;el.innerHTML=`<div class="combo-ctl"><input id="inpInspector" class="combo-input" placeholder="พิมพ์ชื่อผู้ตรวจ" autocomplete="off"><span class="combo-clear">&times;</span><span class="combo-caret">▾</span></div><div class="combo-list"></div>`;const input=el.querySelector('.combo-input'),list=el.querySelector('.combo-list'),clear=el.querySelector('.combo-clear');let active=-1;const people=()=>{const role=AUTH.user?.role||'';if(role==='leader'||role==='inspector')return[AUTH.user?.name||AUTH.user?.username||''];let pool=entries;if(sel['project'])pool=pool.filter(e=>e.project===sel['project']);return uniq([...INSP_SEED,...pool.map(e=>e.inspector)]).filter(Boolean).sort((a,b)=>a.localeCompare(b,'th'));};function render(filter){let opts=people();const f=(filter||'').trim().toLowerCase();if(f)opts=opts.filter(o=>o.toLowerCase().includes(f));active=-1;let html=opts.map(o=>`<div class="combo-opt" data-v="${escAttr(o)}">${esc(o)}</div>`).join('');if(f&&!people().some(o=>o.toLowerCase()===f))html+=`<div class="combo-new" data-new="${escAttr(filter.trim())}">+ ใช้ "${esc(filter.trim())}" (ใหม่)</div>`;if(!html)html=`<div class="combo-empty">พิมพ์ชื่อผู้ตรวจ</div>`;list.innerHTML=html;list.querySelectorAll('.combo-opt').forEach(o=>o.addEventListener('mousedown',e=>{e.preventDefault();pick(o.dataset.v);}));const nw=list.querySelector('.combo-new');if(nw)nw.addEventListener('mousedown',e=>{e.preventDefault();pick(nw.dataset.new);});}function pick(v){input.value=v;el.classList.toggle('has-val',!!v);el.classList.remove('open');}function open(){el.classList.add('open');render(input.value);}input.addEventListener('focus',open);input.addEventListener('click',open);input.addEventListener('input',()=>{el.classList.add('open');el.classList.toggle('has-val',!!input.value);render(input.value);});input.addEventListener('keydown',e=>{const items=list.querySelectorAll('.combo-opt,.combo-new');if(e.key==='ArrowDown'){e.preventDefault();active=Math.min(active+1,items.length-1);}else if(e.key==='ArrowUp'){e.preventDefault();active=Math.max(active-1,0);}else if(e.key==='Enter'){e.preventDefault();if(active>=0){const it=items[active];pick(it.dataset.v||it.dataset.new);}else if(input.value.trim())pick(input.value.trim());return;}else if(e.key==='Escape'){el.classList.remove('open');return;}items.forEach((it,i)=>it.classList.toggle('active',i===active));if(active>=0)items[active].scrollIntoView({block:'nearest'});});input.addEventListener('blur',()=>setTimeout(()=>el.classList.remove('open'),150));clear.addEventListener('mousedown',e=>{e.preventDefault();pick('');});}

/* ─── IMAGE WIRING ──────────────────────────────────────── */
function wireImg(inputId,dropId,setter){$('#'+inputId).addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;const rd=new FileReader();rd.onload=ev=>{const img=new Image();img.onload=()=>{const max=1280;let{width:w,height:h}=img;if(w>h&&w>max){h=Math.round(h*max/w);w=max;}else if(h>=w&&h>max){w=Math.round(w*max/h);h=max;}const c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(img,0,0,w,h);const data=c.toDataURL('image/jpeg',.72);setter(data);const lbl=$('#'+dropId);lbl.classList.add('has-img');lbl.style.backgroundImage=`url(${data})`;const ph=lbl.querySelector('.ph-content');if(ph)ph.style.display='none';};img.src=ev.target.result;};rd.readAsDataURL(f);});}
wireImg('fileMain','dropMain',d=>imgMain=d);
wireImg('fileSticker','dropSticker',d=>imgSticker=d);
wireImg('fileImg3','dropImg3',d=>img3=d);
wireImg('fileImg4','dropImg4',d=>img4=d);

