$('#saveBtn').addEventListener('click',async()=>{
  const insp=$('#inpInspector').value.trim();
  if(!sel.project){toast('กรุณาเลือกโครงการ',false);return;}
  if(!sel.loc){toast('กรุณาเลือกสถานที่',false);return;}
  if(!sel.equip){toast('กรุณาเลือกอุปกรณ์',false);return;}
  if(!imgMain&&!imgSticker){toast('กรุณาแนบรูปอย่างน้อยหนึ่งรูป',false);return;}
  if(!insp){toast('กรุณากรอกชื่อผู้ตรวจ',false);return;}
  const btn=$('#saveBtn');btn.disabled=true;btn.textContent='กำลังบันทึก...';
  const e={id:editingId||uid(),project:sel.project,system:sel.system,typeLocation:sel.typeloc,locName:sel.loc,subName:sel.sub,equipment:sel.equip,serial:sel.serial,brand:$('#inpBrand').value.trim(),model:$('#inpModel').value.trim(),asset:$('#inpAsset').value.trim(),inspector:insp,note:$('#inpNote').value.trim(),imgMain,imgSticker,img3,img4,createdAt:editingId?(entries.find(x=>x.id===editingId)?.createdAt||Date.now()):Date.now()};
  let synced=false;
  if(AUTH.token){btn.textContent='กำลังส่งขึ้นเซิร์ฟเวอร์...';const r=await api(ACT.createRecord,{record:{id:e.id,project:e.project,system:e.system,typeLocation:e.typeLocation,location:e.locName,sublocation:e.subName,equipment:e.equipment,serial:e.serial,brand:e.brand,model:e.model,asset:e.asset,inspector:e.inspector,note:e.note,createdAt:e.createdAt},images:{main:e.imgMain||'',sticker:e.imgSticker||'',img3:e.img3||'',img4:e.img4||''}});synced=!!(r&&r.ok);}
  btn.disabled=false;btn.textContent='บันทึกรายการ';
  resetForm();refreshDerived();updateStats();
  if(synced){toast(editingId?'แก้ไข & ส่งขึ้นเซิร์ฟเวอร์แล้ว':'บันทึก & ส่งขึ้นเซิร์ฟเวอร์แล้ว',true);await loadRecords();}
  else{toast('บันทึกไม่สำเร็จ กรุณาลองใหม่',false);}
  editingId=null;goTab('saved');
});
$('#resetBtn').addEventListener('click',resetForm);
function resetForm(){imgMain='';imgSticker='';editingId=null;img3='';img4='';['fileMain','fileSticker','fileImg3','fileImg4'].forEach(id=>$('#'+id).value='');['dropMain','dropSticker','dropImg3','dropImg4'].forEach(id=>{const l=$('#'+id);l.classList.remove('has-img');l.style.backgroundImage='';const ph=l.querySelector('.ph-content');if(ph)ph.style.display='';});['inpInspector','inpAsset','inpNote'].forEach(id=>$('#'+id).value='');$('#inspCombo').classList.remove('has-val');LEVELS.forEach(lv=>{sel[lv]='';if(combos[lv]){combos[lv].input.value='';combos[lv].el.classList.remove('has-val');}});setDisabledStates();updateBrandModel();const role=AUTH.user?.role||'';const userProjs=(AUTH.user?.project||'').split(',').map(p=>p.trim()).filter(Boolean);if(role==='leader'||role==='inspector'){$('#inpInspector').value=AUTH.user?.name||AUTH.user?.username||'';$('#inpInspector').disabled=true;$('#inspCombo').classList.add('has-val');$('#inspCombo').style.background='#EEF1F4';if(userProjs.length===1){setTimeout(()=>choose('project',userProjs[0]),50);if(combos.project){combos.project.input.disabled=true;combos.project.el.style.background='#EEF1F4';}}}else{$('#inpInspector').disabled=false;$('#inspCombo').style.background='';if(combos.project){combos.project.input.disabled=false;combos.project.el.style.background='';}}$('#addEyebrow').textContent='New Record';$('#addTitle').textContent='เพิ่มรายการใหม่';$('#saveBtn').textContent='บันทึกรายการ';}

/* ─── RECORDS ───────────────────────────────────────────── */
async function loadRecords(){if(!AUTH.token)return;const r=await api(ACT.listRecords,{});if(r&&r.ok&&Array.isArray(r.records)){entries=r.records.map(x=>({id:x.id,project:x.project,system:x.system,typeLocation:x.typeLocation,locName:x.location,subName:x.sublocation,equipment:x.equipment,serial:x.serial,brand:x.brand,model:x.model,asset:x.asset,inspector:x.inspector,note:x.note,imgMain:x.imgMain,imgSticker:x.imgSticker,img3:x.img3,img4:x.img4,thumbMain:x.thumbMain,thumbSticker:x.thumbSticker,thumb3:x.thumb3,thumb4:x.thumb4,createdAt:x.createdAt||Date.now(),synced:true}));entries.sort((a,b)=>b.createdAt-a.createdAt);renderSaved();updateStats();renderDashboard();}}

$('#savedSearch').addEventListener('input',renderSaved);
['savedFProject','savedFSystem','savedFLoc','savedFSub','savedFEquip','savedSort'].forEach(id=>{
  document.getElementById(id)?.addEventListener('change',renderSaved);
});

function fillSavedFilters(){
  const fp=$('#savedFProject'); if(!fp) return;
  const role=AUTH.user?.role||'', userProj=AUTH.user?.project||'';
  const isRestricted=role==='leader'||role==='inspector';
  if(isRestricted&&userProj){
    const userProjs=userProj.split(',').map(p=>p.trim()).filter(Boolean);
    const cur=fp.value;
    fp.innerHTML=userProjs.map(p=>`<option value="${escAttr(p)}">${esc(p)}</option>`).join('');
    if(userProjs.includes(cur)) fp.value=cur; else if(userProjs.length===1) fp.value=userProjs[0];
  } else {
    const projects=uniq(entries.map(e=>e.project)).filter(Boolean).sort((a,b)=>a.localeCompare(b,'th'));
    const prev=fp.value;
    fp.innerHTML='<option value="">ทุกโครงการ</option>'+projects.map(p=>`<option value="${escAttr(p)}">${esc(p)}</option>`).join('');
    if(projects.includes(prev)) fp.value=prev;
  }
  const fillDep=(el,src,key,defLabel)=>{
    if(!el) return;
    const prev=el.value;
    const vals=uniq(src.map(e=>e[key])).filter(Boolean).sort((a,b)=>a.localeCompare(b,'th'));
    el.innerHTML=`<option value="">${defLabel}</option>`+vals.map(v=>`<option value="${escAttr(v)}">${esc(v)}</option>`).join('');
    if(vals.includes(prev)) el.value=prev;
  };
  let sc=entries; if(fp.value) sc=sc.filter(e=>e.project===fp.value);
  fillDep($('#savedFSystem'),sc,'system','ทุกระบบ');
  let sc2=sc; if($('#savedFSystem')&&$('#savedFSystem').value) sc2=sc2.filter(e=>e.system===$('#savedFSystem').value);
  fillDep($('#savedFLoc'),sc2,'locName','ทุกสถานที่');
  let sc3=sc2; if($('#savedFLoc')&&$('#savedFLoc').value) sc3=sc3.filter(e=>e.locName===$('#savedFLoc').value);
  fillDep($('#savedFSub'),sc3,'subName','ทุกสถานที่ย่อย');
  let sc4=sc3; if($('#savedFSub')&&$('#savedFSub').value) sc4=sc4.filter(e=>e.subName===$('#savedFSub').value);
  fillDep($('#savedFEquip'),sc4,'equipment','ทุกอุปกรณ์');
}

// แยกตรรกะ filter/sort ของหน้ารายการที่บันทึกออกมา ให้ปุ่ม "สร้างรายงาน PDF" เรียกใช้รายการชุดเดียวกับที่เห็นบนตารางได้
function getSavedFilteredList(){
  const q=$('#savedSearch')?$('#savedSearch').value.trim().toLowerCase():'';
  const fp=$('#savedFProject')?$('#savedFProject').value:'';
  const fs=$('#savedFSystem')?$('#savedFSystem').value:'';
  const fl=$('#savedFLoc')?$('#savedFLoc').value:'';
  const fsub=$('#savedFSub')?$('#savedFSub').value:'';
  const feq=$('#savedFEquip')?$('#savedFEquip').value:'';
  const sortVal=$('#savedSort')?$('#savedSort').value:'newest';
  let list=entries.filter(e=>!q||[e.project,e.system,e.locName,e.subName,e.equipment,e.brand,e.model,e.serial,e.inspector,e.note].join(' ').toLowerCase().includes(q));
  if(fp)list=list.filter(e=>e.project===fp);
  if(fs)list=list.filter(e=>e.system===fs);
  if(fl)list=list.filter(e=>e.locName===fl);
  if(fsub)list=list.filter(e=>e.subName===fsub);
  if(feq)list=list.filter(e=>e.equipment===feq);
  if(sortVal==='newest')list.sort((a,b)=>b.createdAt-a.createdAt);
  else if(sortVal==='oldest')list.sort((a,b)=>a.createdAt-b.createdAt);
  else if(sortVal==='az')list.sort((a,b)=>(a.equipment||'').localeCompare(b.equipment||''));
  else if(sortVal==='za')list.sort((a,b)=>(b.equipment||'').localeCompare(a.equipment||''));
  else if(sortVal==='proj_th_az')list.sort((a,b)=>(a.project||'').localeCompare(b.project||'','th'));
  else if(sortVal==='proj_th_za')list.sort((a,b)=>(b.project||'').localeCompare(a.project||'','th'));
  else if(sortVal==='proj_en_az')list.sort((a,b)=>(a.project||'').localeCompare(b.project||'','en'));
  else if(sortVal==='proj_en_za')list.sort((a,b)=>(b.project||'').localeCompare(a.project||'','en'));
  return list;
}
function renderSaved(){
  fillSavedFilters();
  const list=getSavedFilteredList();
  $('#savedPill').textContent=entries.length;
  const grid=$('#savedGrid');
  if(!list.length){grid.innerHTML=`<div class="empty"><b>${entries.length?'ไม่พบรายการตามเงื่อนไข':'ยังไม่มีรายการที่บันทึก'}</b></div>`;return;}
  grid.innerHTML=list.map(e=>{const thumb=e.thumbMain||e.thumbSticker||e.imgMain||e.imgSticker||'';const n=(e.imgMain?1:0)+(e.imgSticker?1:0);const title=esc([e.equipment,e.brand,e.model].filter(Boolean).join(' · '))||'(ไม่ระบุอุปกรณ์)';const loc=esc([e.project,e.locName,e.subName].filter(Boolean).join(' › '));return `<div class="rrow" data-id="${e.id}"><div class="thumb" style="background-image:url(${thumb})">${n?`<span class="cnt">${n} รูป</span>`:''}</div><div class="body"><div class="tt">${title}</div>${loc?`<div class="loc">${loc}</div>`:''}<div class="meta"><span>${esc(e.inspector||'-')}</span>${e.serial?`<span>SN: ${esc(e.serial)}</span>`:''}<span>${fmtDate(e.createdAt,true)}</span></div></div><div class="acts">${canEdit()?'<button data-act="edit">แก้ไข</button>':''}<button data-act="img">รูป</button>${canDelete()?'<button data-act="del" class="del">ลบ</button>':''}</div></div>`;}).join('');
  grid.querySelectorAll('.rrow').forEach(c=>{const id=c.dataset.id;const be=c.querySelector('[data-act="edit"]');if(be)be.onclick=()=>editEntry(id);c.querySelector('[data-act="img"]').onclick=()=>downloadImgs(id);const bd=c.querySelector('[data-act="del"]');if(bd)bd.onclick=()=>delEntry(id);});
}
function editEntry(id){const e=entries.find(x=>x.id===id);if(!e)return;resetForm();editingId=id;imgMain=e.imgMain||'';imgSticker=e.imgSticker||'';img3=e.img3||'';img4=e.img4||'';choose('project',e.project||'');choose('system',e.system||'');choose('loc',e.locName||'');choose('sub',e.subName||'');choose('equip',e.equipment||'');choose('serial',e.serial||'');if($('#inpBrand'))$('#inpBrand').value=e.brand||'';if($('#inpModel'))$('#inpModel').value=e.model||'';$('#inpAsset').value=e.asset||'';$('#inpInspector').value=e.inspector||'';$('#inspCombo').classList.toggle('has-val',!!e.inspector);$('#inpNote').value=e.note||'';$('#addEyebrow').textContent='Edit Record';$('#addTitle').textContent='แก้ไขรายการ';$('#saveBtn').textContent='บันทึกการแก้ไข';goTab('add');window.scrollTo(0,0);}
async function delEntry(id){if(!confirm('ลบรายการนี้ถาวร?'))return;if(AUTH.token){const r=await api(ACT.deleteRecord,{id});if(r&&r.ok){await loadRecords();toast('ลบรายการแล้ว',true);}else toast((r&&r.message)||'ลบไม่สำเร็จ',false);}}
function downloadImgs(id){const e=entries.find(x=>x.id===id);if(!e)return;const isData=u=>String(u).startsWith('data:');let n=0;[['main',e.imgMain],['sticker',e.imgSticker],['img3',e.img3],['img4',e.img4]].forEach(([k,u],i)=>{if(!u)return;n++;setTimeout(()=>{if(isData(u)){const a=document.createElement('a');a.href=u;a.download=`img_${k}.jpg`;a.click();}else window.open(u,'_blank');},i*300);});if(n)toast(`เปิด/ดาวน์โหลดรูป ${n} ไฟล์`,true);else toast('ไม่มีรูป',false);}

/* ─── DASHBOARD ─────────────────────────────────────────── */
let progressCache=[];
async function loadProgress(){if(!AUTH.token)return;const r=await api(ACT.getProgress,{});if(r&&r.ok&&Array.isArray(r.progress)){progressCache=r.progress;if(canSeeDashboard())renderProgress();renderSavedProgress();renderLeaderDashboard();}}
document.addEventListener('DOMContentLoaded',()=>{const df=$('#dashMainFilter');if(df)df.addEventListener('change',renderDashboard);});

function renderDashboard(){if(!canSeeDashboard())return;const role=(AUTH.user&&AUTH.user.role)||'';const leaderProjs=(role==='leader')?(AUTH.user?.project||'').split(',').map(p=>p.trim()).filter(Boolean):[];const baseEntries=(role==='leader'&&leaderProjs.length>0)?entries.filter(e=>leaderProjs.includes(e.project)):entries;const df=$('#dashMainFilter');const sel_proj=df?df.value:'__all';const isAll=!sel_proj||sel_proj==='__all';const filtered=isAll?baseEntries:baseEntries.filter(e=>e.project===sel_proj);let withImg=0,days={};filtered.forEach(e=>{if(e.imgMain||e.imgSticker)withImg++;const d=new Date(e.createdAt);const key=`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;days[key]=(days[key]||0)+1;});const total=filtered.length;const projCount=uniq(filtered.map(e=>e.project)).filter(Boolean).length;const td=new Date();const tkey=`${td.getFullYear()}-${pad(td.getMonth()+1)}-${pad(td.getDate())}`;const todayN=days[tkey]||0;$('#kpiRow').innerHTML=`<div class="kpi accent"><div class="k-lbl">รายการทั้งหมด</div><div class="k-num">${total}</div></div><div class="kpi"><div class="k-lbl">วันนี้</div><div class="k-num">${todayN}</div></div><div class="kpi"><div class="k-lbl">โครงการ</div><div class="k-num">${projCount}</div></div><div class="kpi"><div class="k-lbl">มีรูปภาพ</div><div class="k-num">${total?Math.round(withImg/total*100):0}%</div></div>`;renderDailyChart(filtered);const allProjs=uniq(baseEntries.map(e=>e.project)).filter(Boolean).sort();if(df){const cur=df.value;df.innerHTML='<option value="__all">ทุกโครงการ</option>'+allProjs.map(p=>`<option value="${escAttr(p)}">${esc(p)}</option>`).join('');df.value=cur;}if(progressCache.length)renderProgress();}

function renderProgress(){const df=$('#dashMainFilter');const pick=df?df.value:'__all';const list=(!pick||pick==='__all')?progressCache:progressCache.filter(p=>p.project===pick);const tot=list.reduce((a,p)=>a+p.total,0),done=list.reduce((a,p)=>a+p.done,0),remain=Math.max(0,tot-done),pct=tot?Math.round(done/tot*100):0;$('#progSummary').innerHTML=`<div class="prog-cards"><div class="prog-c"><div class="v">${tot}</div><div>ทั้งหมด</div></div><div class="prog-c"><div class="v" style="color:var(--ok)">${done}</div><div>ทำแล้ว</div></div><div class="prog-c"><div class="v" style="color:var(--danger)">${remain}</div><div>คงเหลือ</div></div><div class="prog-c"><div class="v" style="color:var(--accent)">${pct}%</div><div>คืบหน้า</div></div></div>`;const pctEl=$('#progTotalPct');if(pctEl)pctEl.textContent=tot?pct+'%':'—';const chart=$('#progChart');if(!list.length){chart.innerHTML='';return;}chart.innerHTML=list.map(p=>{const w=p.total?Math.round(p.done/p.total*100):0;const color=w>=80?'#22C55E':w>=40?'#F97316':'#EF4444';return `<div class="prog-row"><span class="pl">${esc(p.project)}</span><div class="prog-track"><div class="prog-fill" style="width:${w}%;background:${color}"></div></div><span class="pn" style="color:${color};font-weight:600">${p.done}/${p.total} (${w}%)</span></div>`;}).join('');}

function renderDailyChart(filtered){const chartEl=$('#chartDaily');if(!chartEl)return;const N=14,today=new Date();today.setHours(0,0,0,0);const dateKeys=[];for(let i=N-1;i>=0;i--){const d=new Date(today);d.setDate(d.getDate()-i);dateKeys.push({key:`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`,lbl:`${d.getDate()}/${d.getMonth()+1}`});}const days={};(filtered||entries).forEach(e=>{const d=new Date(e.createdAt);const key=`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;days[key]=(days[key]||0)+1;});const vals=dateKeys.map(dk=>days[dk.key]||0);const max=Math.max(1,...vals);const W=700,H=200,pl=32,pb=26,pt=12,pr=12;let bars='',xl='',gl='';const cw=(W-pl-pr)/N,bw=cw*.62;vals.forEach((v,i)=>{const x=pl+i*cw+(cw-bw)/2;const h=(H-pb-pt)*(v/max);const y=H-pb-h;bars+=`<rect x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${bw.toFixed(1)}" height="${Math.max(h,0).toFixed(1)}" fill="var(--accent)" rx="2" opacity="${v?1:.08}"><title>${dateKeys[i].lbl}: ${v}</title></rect>`;if(v>0)bars+=`<text x="${(x+bw/2).toFixed(1)}" y="${(y-3).toFixed(1)}" text-anchor="middle" style="font-size:10px;fill:var(--accent);font-weight:600">${v}</text>`;if(i%2===0||i===N-1)xl+=`<text x="${(x+bw/2).toFixed(1)}" y="${H-pb+14}" text-anchor="middle" style="font-size:9px;fill:var(--ink-faint)">${dateKeys[i].lbl}</text>`;});const steps=Math.min(max,4);for(let s=0;s<=steps;s++){const yv=Math.round(max*s/steps);const yy=H-pb-(H-pb-pt)*s/steps;gl+=`<line x1="${pl}" y1="${yy.toFixed(1)}" x2="${W-pr}" y2="${yy.toFixed(1)}" stroke="var(--line)" stroke-width="${s?0.5:1}"/><text x="${pl-5}" y="${(yy+3).toFixed(1)}" text-anchor="end" style="font-size:9px;fill:var(--ink-faint)">${yv}</text>`;}chartEl.innerHTML=`<svg class="bar-svg" viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMid meet">${gl}${bars}${xl}<line stroke="var(--ink-faint)" x1="${pl}" y1="${H-pb}" x2="${W-pr}" y2="${H-pb}"/></svg>`;}

function renderSavedProgress(){const role=(AUTH.user&&AUTH.user.role)||'';const box=$('#savedProgress');if(!box)return;const show=(role==='leader'||role==='manager'||role==='admin')&&progressCache.length;box.style.display=show?'':'none';if(!show)return;const sel_f=$('#savedProgFilter');const multi=(role==='manager'||role==='admin');sel_f.style.display=multi?'':'none';if(multi){const cur=sel_f.value;sel_f.innerHTML=['<option value="__all">ทุกโครงการ</option>'].concat(progressCache.map(p=>`<option value="${esc(p.project)}">${esc(p.project)}</option>`)).join('');if(cur&&[...sel_f.options].some(o=>o.value===cur))sel_f.value=cur;sel_f.onchange=()=>renderSavedProgress();}const pick=multi?sel_f.value:'__all';const list=(pick==='__all')?progressCache:progressCache.filter(p=>p.project===pick);const tot=list.reduce((a,p)=>a+p.total,0),done=list.reduce((a,p)=>a+p.done,0),remain=Math.max(0,tot-done),pct=tot?Math.round(done/tot*100):0;let html=`<div class="prog-cards"><div class="prog-c"><div class="v">${tot}</div><div>ทั้งหมด</div></div><div class="prog-c"><div class="v" style="color:var(--ok)">${done}</div><div>ทำแล้ว</div></div><div class="prog-c"><div class="v" style="color:var(--danger)">${remain}</div><div>คงเหลือ</div></div><div class="prog-c"><div class="v" style="color:var(--accent)">${pct}%</div><div>คืบหน้า</div></div></div>`;html+=list.map(p=>{const w=p.total?Math.round(p.done/p.total*100):0;return `<div class="prog-row"><span class="pl">${esc(p.project)}</span><div class="prog-track"><div class="prog-fill" style="width:${w}%"></div></div><span class="pn">${p.done}/${p.total} (${w}%)</span></div>`;}).join('');$('#savedProgBody').innerHTML=html;}

/* ─── LEADER DONUT ──────────────────────────────────────── */
const DONUT_COLORS=['#EE7C16','#3B82F6','#10B981','#8B5CF6','#EC4899','#F59E0B','#14B8A6','#6366F1','#EF4444','#84CC16'];
let targetsCache=[];
async function loadTargets(){if(!AUTH.token)return;const role=(AUTH.user&&AUTH.user.role)||'';if(!['admin','manager','leader'].includes(role))return;const r=await api('listTargets',{});if(r&&r.ok)targetsCache=r.targets||[];}
function getTargetForProject(proj){const username=AUTH.user?.username||'',role=AUTH.user?.role||'';return targetsCache.find(t=>t.project===proj&&(role!=='leader'||t.username===username));}
function deadlineLabel(deadline){if(!deadline)return '<span style="color:var(--ink-faint)">ยังไม่ได้ตั้ง</span>';const d=new Date(deadline),now=new Date();now.setHours(0,0,0,0);const diff=Math.ceil((d-now)/(1000*60*60*24));const fmt=`${pad(d.getDate())}/${pad(d.getMonth()+1)}/${d.getFullYear()+543}`;if(diff<0)return `<span class="deadline-over">⚠ เลยกำหนด ${Math.abs(diff)} วัน (${fmt})</span>`;if(diff<=7)return `<span class="deadline-warn">⏰ เหลือ ${diff} วัน (${fmt})</span>`;return `<span class="deadline-ok">✅ ${fmt} (เหลือ ${diff} วัน)</span>`;}
function renderLeaderDashboard(){const role=(AUTH.user&&AUTH.user.role)||'';const sec=$('#leaderDashSection');if(!sec)return;if(role!=='leader'){sec.style.display='none';return;}if(!progressCache.length){sec.style.display='none';return;}sec.style.display='';const list=progressCache;const totalAll=list.reduce((a,p)=>a+p.total,0);const doneAll=list.reduce((a,p)=>a+p.done,0);const pctAll=totalAll?Math.round(doneAll/totalAll*100):0;if($('#leaderDonutPct'))$('#leaderDonutPct').textContent=pctAll+'%';const svg=$('#leaderDonutSvg');const cx=100,cy=100,R=80,r=52;let startAngle=-Math.PI/2,paths='';list.forEach((p,i)=>{const frac=totalAll?p.total/totalAll:1/list.length;const angle=frac*2*Math.PI;const endAngle=startAngle+angle;const x1=cx+R*Math.cos(startAngle),y1=cy+R*Math.sin(startAngle);const x2=cx+R*Math.cos(endAngle),y2=cy+R*Math.sin(endAngle);const ix1=cx+r*Math.cos(startAngle),iy1=cy+r*Math.sin(startAngle);const ix2=cx+r*Math.cos(endAngle),iy2=cy+r*Math.sin(endAngle);const large=angle>Math.PI?1:0;const color=DONUT_COLORS[i%DONUT_COLORS.length];const pct=p.total?Math.round(p.done/p.total*100):0;paths+=`<path class="donut-seg" d="M${x1.toFixed(2)},${y1.toFixed(2)} A${R},${R} 0 ${large},1 ${x2.toFixed(2)},${y2.toFixed(2)} L${ix2.toFixed(2)},${iy2.toFixed(2)} A${r},${r} 0 ${large},0 ${ix1.toFixed(2)},${iy1.toFixed(2)} Z" fill="${color}" data-proj="${escAttr(p.project)}"><title>${esc(p.project)}: ${p.done}/${p.total} (${pct}%)</title></path>`;startAngle=endAngle;});svg.innerHTML=paths;svg.querySelectorAll('.donut-seg').forEach(seg=>seg.addEventListener('click',()=>openProjDetail(seg.dataset.proj)));$('#leaderDonutList').innerHTML=list.map((p,i)=>{const pct=p.total?Math.round(p.done/p.total*100):0;const color=DONUT_COLORS[i%DONUT_COLORS.length];const t=getTargetForProject(p.project);return `<div class="proj-item" onclick="openProjDetail('${escAttr(p.project)}')"><div class="proj-dot" style="background:${color}"></div><div style="flex:1;min-width:0"><div style="font-size:13px;font-weight:600">${esc(p.project)}</div><div class="proj-bar-track" style="margin:4px 0"><div class="proj-bar-fill" style="width:${pct}%;background:${color}"></div></div><div style="font-size:11px">${p.done}/${p.total} (${pct}%)</div><div style="font-size:11px;margin-top:2px">${t?deadlineLabel(t.deadline):'<span style="color:var(--ink-faint)">ยังไม่ได้ตั้ง target</span>'}</div></div></div>`;}).join('');if($('#leaderDonutLegend'))$('#leaderDonutLegend').textContent=`${list.length} โครงการ · ${doneAll}/${totalAll} รายการ`;}

function openProjDetail(proj){const p=progressCache.find(x=>x.project===proj);if(!p)return;const i=progressCache.indexOf(p);const color=DONUT_COLORS[i%DONUT_COLORS.length];const pct=p.total?Math.round(p.done/p.total*100):0;const remain=Math.max(0,p.total-p.done);const t=getTargetForProject(proj);const statusColor=pct>=80?'#22C55E':pct>=40?'#F97316':'#EF4444';$('#projDetailContent').innerHTML=`<div style="display:flex;align-items:center;gap:10px;margin-bottom:16px"><div style="width:14px;height:14px;border-radius:50%;background:${color};flex:none"></div><h3>${esc(proj)}</h3></div><div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;margin-bottom:16px"><div style="background:#F7F9FB;border-radius:10px;padding:12px;text-align:center"><div style="font-size:22px;font-weight:700">${p.total}</div><div style="font-size:11px;color:var(--ink-soft)">งานทั้งหมด</div></div><div style="background:#F7F9FB;border-radius:10px;padding:12px;text-align:center"><div style="font-size:22px;font-weight:700;color:#22C55E">${p.done}</div><div style="font-size:11px;color:var(--ink-soft)">ทำแล้ว</div></div><div style="background:#F7F9FB;border-radius:10px;padding:12px;text-align:center"><div style="font-size:22px;font-weight:700;color:#EF4444">${remain}</div><div style="font-size:11px;color:var(--ink-soft)">คงเหลือ</div></div></div><div style="background:#F7F9FB;border-radius:10px;padding:14px;margin-bottom:14px"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px"><span style="font-size:13px;font-weight:600">ความคืบหน้า</span><span style="font-weight:700;color:${statusColor}">${pct}%</span></div><div style="background:var(--line-soft);border-radius:6px;height:14px;overflow:hidden"><div style="width:${pct}%;height:100%;background:${statusColor};border-radius:6px;transition:width .5s"></div></div></div><div class="target-form"><div style="font-size:13px;font-weight:600;margin-bottom:10px">${t?'แก้ไข':'ตั้ง'} Target วันเสร็จ</div><label style="font-size:12px;font-weight:500;display:block;margin-bottom:4px">วันที่กำหนดเสร็จ</label><input type="date" class="tin" id="targetDate" style="width:100%;margin-bottom:10px" value="${t?t.deadline.split('T')[0]:''}"><label style="font-size:12px;font-weight:500;display:block;margin-bottom:4px">หมายเหตุ</label><input type="text" class="tin" id="targetNote" style="width:100%;margin-bottom:12px" placeholder="เช่น ตามสัญญา..." value="${t?esc(t.note||''):''}"><button class="btn btn-primary" style="width:100%" onclick="saveTargetForProj('${escAttr(proj)}')">💾 บันทึก Target</button><div id="targetSaveMsg" style="margin-top:8px;font-size:12px;text-align:center"></div></div>`;$('#projDetailModal').style.display='flex';}
async function saveTargetForProj(proj){const deadline=$('#targetDate').value,note=$('#targetNote').value.trim(),msg=$('#targetSaveMsg');if(!deadline){msg.innerHTML='<span style="color:#EF4444">กรุณาเลือกวันที่</span>';return;}msg.innerHTML='<span style="color:var(--ink-soft)">กำลังบันทึก...</span>';const r=await api('saveTarget',{project:proj,deadline,note});if(r&&r.ok){msg.innerHTML='<span style="color:#22C55E">✅ บันทึกแล้ว</span>';await loadTargets();renderLeaderDashboard();setTimeout(()=>{$('#projDetailModal').style.display='none';},800);}else msg.innerHTML=`<span style="color:#EF4444">❌ ${esc((r&&r.message)||'เกิดข้อผิดพลาด')}</span>`;}

/* ─── MASTER TABLE ──────────────────────────────────────── */
function fillMasterFilters(){
  const fp=$('#masterFProject'); if(!fp) return;
  const projects=uniq(master.map(m=>m.project)).filter(Boolean).sort((a,b)=>a.localeCompare(b,'th'));
  const prev=fp.value;
  fp.innerHTML='<option value="">ทุกโครงการ</option>'+projects.map(p=>`<option value="${escAttr(p)}">${esc(p)}</option>`).join('');
  if(projects.includes(prev)) fp.value=prev;
  const fillDep=(el,src,key,defLabel)=>{
    if(!el) return;
    const prevV=el.value;
    const vals=uniq(src.map(m=>m[key])).filter(Boolean).sort((a,b)=>a.localeCompare(b,'th'));
    el.innerHTML=`<option value="">${defLabel}</option>`+vals.map(v=>`<option value="${escAttr(v)}">${esc(v)}</option>`).join('');
    if(vals.includes(prevV)) el.value=prevV;
  };
  let sc=master; if(fp.value) sc=sc.filter(m=>m.project===fp.value);
  fillDep($('#masterFSystem'),sc,'system','ทุกระบบ');
  let sc2=sc; if($('#masterFSystem')&&$('#masterFSystem').value) sc2=sc2.filter(m=>m.system===$('#masterFSystem').value);
  fillDep($('#masterFLoc'),sc2,'locName','ทุกสถานที่');
  let sc3=sc2; if($('#masterFLoc')&&$('#masterFLoc').value) sc3=sc3.filter(m=>m.locName===$('#masterFLoc').value);
  fillDep($('#masterFSub'),sc3,'subName','ทุกสถานที่ย่อย');
  let sc4=sc3; if($('#masterFSub')&&$('#masterFSub').value) sc4=sc4.filter(m=>m.subName===$('#masterFSub').value);
  fillDep($('#masterFEquip'),sc4,'equipment','ทุกอุปกรณ์');
}

function renderMaster(){
  fillMasterFilters();
  const q=$('#masterSearch')?$('#masterSearch').value.trim().toLowerCase():'';
  const fp=$('#masterFProject')?$('#masterFProject').value:'';
  const fs=$('#masterFSystem')?$('#masterFSystem').value:'';
  const fl=$('#masterFLoc')?$('#masterFLoc').value:'';
  const fsub=$('#masterFSub')?$('#masterFSub').value:'';
  const feq=$('#masterFEquip')?$('#masterFEquip').value:'';
  const fmiss=$('#masterFMissing')?$('#masterFMissing').value:'';
  let list=master.filter(m=>!q||[m.project,m.system,m.typeLocation,m.locName,m.subName,m.equipment,m.brand,m.model,m.asset,m.serial].join(' ').toLowerCase().includes(q));
  if(fp)list=list.filter(m=>m.project===fp);
  if(fs)list=list.filter(m=>m.system===fs);
  if(fl)list=list.filter(m=>m.locName===fl);
  if(fsub)list=list.filter(m=>m.subName===fsub);
  if(feq)list=list.filter(m=>m.equipment===feq);
  if(fmiss==='brand') list=list.filter(m=>!m.brand);
  else if(fmiss==='model') list=list.filter(m=>!m.model);
  else if(fmiss==='serial') list=list.filter(m=>!m.serial);
  else if(fmiss==='any') list=list.filter(m=>!m.brand||!m.model||!m.serial);
  const body=$('#masterBody');if($('#masterPill'))$('#masterPill').textContent=master.length;
  if(!list.length){body.innerHTML=`<tr><td colspan="12" style="text-align:center;padding:30px;color:var(--ink-faint)">${master.length?'ไม่พบข้อมูลตามเงื่อนไข':'ยังไม่มีข้อมูล'}</td></tr>`;return;}
  body.innerHTML=list.map(m=>`<tr data-id="${m.id}"><td class="codecell" style="text-align:center">${esc(m.order)}</td><td>${esc(m.project)}</td><td>${esc(m.system)}</td><td>${esc(m.typeLocation)}</td><td>${esc(m.locName)}</td><td>${esc(m.subName)}</td><td>${esc(m.equipment)}</td><td>${esc(m.brand)}</td><td>${esc(m.model)}</td><td class="codecell">${esc(m.asset)}</td><td class="codecell">${esc(m.serial)}</td><td>${canEdit()?`<div class="rowact"><button class="icon-btn" data-act="edit">✎</button><button class="icon-btn del" data-act="del">🗑</button></div>`:'—'}</td></tr>`).join('');
  body.querySelectorAll('tr').forEach(tr=>{const id=tr.dataset.id;const be=tr.querySelector('[data-act="edit"]');if(be)be.onclick=()=>editMaster(id);const bd=tr.querySelector('[data-act="del"]');if(bd)bd.onclick=()=>delMaster(id);});
}
$('#addMasterBtn').addEventListener('click',()=>editMaster(null));
function editMaster(id){
  const m=id?master.find(x=>x.id===id):{project:'',system:'',typeLocation:'',locName:'',subName:'',equipment:'',brand:'',model:'',asset:'',serial:'',order:''};
  if(!m)return;
  let dlg=$('#masterDialog');
  if(!dlg){
    dlg=document.createElement('div'); dlg.id='masterDialog';
    dlg.style.cssText='position:fixed;inset:0;z-index:300;background:rgba(20,26,34,.55);display:flex;align-items:center;justify-content:center;padding:20px';
    document.body.appendChild(dlg);
  }
  const F=[
    ['project','โครงการ',true],['system','ระบบ',false],['typeLocation','ประเภทสถานที่',false],
    ['locName','สถานที่',false],['subName','สถานที่ย่อย',false],
    ['equipment','อุปกรณ์',true],['brand','ยี่ห้อ',false],
    ['model','รุ่น',false],['asset','รหัสอุปกรณ์',false],['serial','Serial Number',false],
    ['order','ลำดับ (สำหรับ gen Word/PDF — เว้นว่าง = เรียง ก-ฮ)',false]
  ];
  const fields=F.map(([k,label,req])=>`<div style="margin-bottom:10px">
      <label style="font-size:12px;font-weight:500;display:block;margin-bottom:4px">${label}${req?' <span style="color:#E2231A">*</span>':''}</label>
      <input class="tin mfield" data-k="${k}" value="${escAttr(m[k]||'')}" style="width:100%" placeholder="${label}" autocomplete="off">
    </div>`).join('');
  dlg.innerHTML=`<div style="background:#fff;border-radius:16px;max-width:520px;width:100%;padding:24px;box-shadow:var(--shadow-lift);max-height:90vh;overflow:auto">
    <h3 style="font-size:17px;font-weight:700;margin-bottom:4px">${id?'แก้ไขอุปกรณ์':'เพิ่มอุปกรณ์'}</h3>
    <div style="font-size:12.5px;color:var(--ink-soft);margin-bottom:16px">แก้ได้เฉพาะช่องที่ต้องการ · พิมพ์แล้วเลือกจากค่าที่มีอยู่ของโครงการเดียวกันได้เลย</div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:0 14px">${fields}</div>
    <div style="display:flex;gap:8px;margin-top:14px">
      <button class="btn btn-soft" id="mCancel" style="flex:1">ยกเลิก</button>
      <button class="btn btn-primary" id="mSave" style="flex:1">${id?'บันทึกการแก้ไข':'เพิ่ม'}</button>
    </div></div>`;
  // เรียงตามลำดับ: โครงการ → ระบบ → ประเภทสถานที่ → สถานที่ → สถานที่ย่อย → อุปกรณ์ — ตัวเลือกของแต่ละช่อง
  // กรองจากค่าที่ "เลือกไว้ก่อนหน้า" เท่านั้น กันไม่ให้เห็น/เลือกค่าข้ามโครงการกันได้เหมือนเดิม
  const HIER=['project','system','typeLocation','locName','subName','equipment'];
  const fieldVal=(k)=>{const el=dlg.querySelector(`.mfield[data-k="${k}"]`);return el?el.value.trim():'';};
  const cascadeOptions=(level)=>{
    let rows=master;
    for(const lv of HIER){ if(lv===level)break; const v=fieldVal(lv); if(v) rows=rows.filter(r=>String(r[lv]||'')===v); }
    return uniq(rows.map(r=>r[level])).filter(Boolean);
  };
  const equipScopedOptions=(field)=>{
    let rows=master;
    const proj=fieldVal('project'), equip=fieldVal('equipment');
    if(proj) rows=rows.filter(r=>String(r.project||'')===proj);
    if(equip) rows=rows.filter(r=>String(r.equipment||'')===equip);
    return uniq(rows.map(r=>r[field])).filter(Boolean);
  };
  HIER.forEach(k=>{
    const el=dlg.querySelector(`.mfield[data-k="${k}"]`);
    if(el) upgradeToCombo(el,()=>k==='project'?uniq(master.map(r=>r.project)).filter(Boolean):cascadeOptions(k));
  });
  ['brand','model','asset','serial'].forEach(k=>{
    const el=dlg.querySelector(`.mfield[data-k="${k}"]`);
    if(el) upgradeToCombo(el,()=>equipScopedOptions(k));
  });
  dlg.style.display='flex';
  dlg.querySelector('#mCancel').onclick=()=>dlg.style.display='none';
  dlg.querySelector('#mSave').onclick=()=>{
    const vals={};
    dlg.querySelectorAll('.mfield').forEach(inp=>{vals[inp.dataset.k]=inp.value.trim();});
    if(!vals.project||!vals.equipment){toast('ต้องมีโครงการและอุปกรณ์',false);return;}
    const obj={id:id||uid(),...vals};
    if(id)master=master.map(x=>x.id===id?obj:x);else master.push(obj);
    dlg.style.display='none';
    persistMaster();toast(id?'แก้ไขแล้ว':'เพิ่มอุปกรณ์แล้ว',true);
  };
}
