// ดึงรูปผ่าน backend (UrlFetchApp) แทน fetch() ตรงจาก browser — เลี่ยงปัญหา CORS ของ drive.google.com
async function fetchImageBuffer(url){
  if(!url) return null;
  try{
    const m=String(url).match(/[-\w]{25,}/);
    if(m) url=`https://drive.google.com/thumbnail?id=${m[0]}&sz=w800`;
    const r=await api('fetchImageAsBase64',{url});
    if(!r||!r.ok||!r.base64) return null;
    const bin=atob(r.base64); const len=bin.length; const buf=new Uint8Array(len);
    for(let i=0;i<len;i++) buf[i]=bin.charCodeAt(i);
    return buf.buffer;
  }catch(e){ return null; }
}

// เหมือน fetchImageBuffer แต่คืนเป็น data: URL string ตรงๆ ใช้กับ <img src> ในรายงาน PDF (html2canvas)
// ต้องแปลงเป็น data URI ก่อนเสมอ ไม่ใส่ลิงก์ Drive ตรงๆ เพราะ html2canvas วาดรูป cross-origin ที่ไม่มี CORS header ลงบน canvas ไม่ได้ (ภาพจะหายไปเงียบๆ)
async function fetchImageDataUrl(url){
  if(!url) return '';
  if(String(url).startsWith('data:')) return url;
  try{
    const m=String(url).match(/[-\w]{25,}/);
    let u=url; if(m) u=`https://drive.google.com/thumbnail?id=${m[0]}&sz=w800`;
    const r=await api('fetchImageAsBase64',{url:u});
    if(!r||!r.ok||!r.base64) return '';
    return `data:${r.mimeType||'image/jpeg'};base64,${r.base64}`;
  }catch(e){ return ''; }
}

