/* สร้างไฟล์ PDF จริง — แบ่งเป็น "หน้า" เอง (1 อุปกรณ์ = 1 หน้า) พร้อม header/footer ซ้ำทุกหน้า
   เพราะ html2pdf/html2canvas capture เป็นภาพยาวภาพเดียวแล้วค่อยตัด ไม่ใช่การพิมพ์แบ่งหน้าจริง
   ต้องกำหนดจุดตัดหน้า (page-break-after) เองให้ตรงทุกครั้ง */
async function generatePdfFile(list,fields){
  if(typeof html2pdf==='undefined'){toast('ไลบรารี PDF ยังโหลดไม่เสร็จ ลองใหม่',false);return;}
  showPdfGenOverlay(true,'กำลังโหลดรูปภาพ...');
  const logo=LOGO_SRC||'';
  const reportName=fields.reportName,contract=fields.contract,contractNo=fields.contractNo;
  // ถ้าชื่อสัญญา/โครงการที่กรอกตรงกับโครงการจริง กรองข้อมูลเหลือแค่โครงการนั้นด้วย (เผื่อลืม set filter ในตาราง)
  if(contract && master.some(m=>m.project===contract)){
    const scoped=list.filter(e=>e.project===contract);
    if(scoped.length) list=scoped;
  }
  const headerHtml=`<div class="rpt-runhead">${logo?`<img src="${logo}" alt="AMR">`:'<b style="color:#E2231A">AMR ASIA</b>'}<div class="ct">${esc(contract||reportName)}<br>สัญญาเลขที่ ${esc(contractNo)}</div></div>`;
  const cell=(url,cap)=>url?`<div class="cell"><img src="${url}"><div class="cap">${cap}</div></div>`:'';
  const useTypeLoc=list.some(e=>e.typeLocation);
  const orderMap=buildMasterOrderMap();
  const byOrderThenAlpha=(getItemsA,getItemsB,a,b)=>{
    const oa=Math.min(...getItemsA.map(e=>masterOrderOf(orderMap,e)));
    const ob=Math.min(...getItemsB.map(e=>masterOrderOf(orderMap,e)));
    if(oa!==ob) return oa-ob;
    return a.localeCompare(b,'th');
  };
  const sortItemsByOrder=(items)=>items.slice().sort((a,b)=>{
    const oa=masterOrderOf(orderMap,a),ob=masterOrderOf(orderMap,b);
    if(oa===Infinity&&ob===Infinity) return 0;
    return oa-ob;
  });
  const seq=[]; // [{heading, e}] — heading จะมีค่าแค่รายการแรกของกลุ่มนั้น
  if(useTypeLoc){
    const typeGroups={};list.forEach(e=>{const tk=e.typeLocation||'(ไม่ระบุประเภทสถานที่)';(typeGroups[tk]=typeGroups[tk]||[]).push(e);});
    Object.keys(typeGroups).sort((a,b)=>byOrderThenAlpha(typeGroups[a],typeGroups[b],a,b)).forEach((tname,ti)=>{
      let first=true;
      const locGroups={};typeGroups[tname].forEach(e=>{const lk=e.locName||'(ไม่ระบุสถานที่)';(locGroups[lk]=locGroups[lk]||[]).push(e);});
      Object.keys(locGroups).sort((a,b)=>byOrderThenAlpha(locGroups[a],locGroups[b],a,b)).forEach(lname=>{
        sortItemsByOrder(locGroups[lname]).forEach(e=>{
          seq.push({heading:first?`<div class="rpt-proj-heading">${ti+1}. ${esc(tname)}</div>`:'',e});
          first=false;
        });
      });
    });
  }else{
    const projMap={};list.forEach(e=>{const proj=e.project||'(ไม่ระบุ)';(projMap[proj]=projMap[proj]||[]).push(e);});
    Object.keys(projMap).sort((a,b)=>byOrderThenAlpha(projMap[a],projMap[b],a,b)).forEach((proj,pi)=>{
      sortItemsByOrder(projMap[proj]).forEach((e,idx)=>{
        seq.push({heading:idx===0?`<div class="rpt-proj-heading">${pi+1}. ${esc(proj)}</div>`:'',e});
      });
    });
  }
  const totalPages=seq.length;
  // ต้องดึงรูปเป็น data URI ก่อนใส่ <img src> เสมอ (html2canvas วาดรูป cross-origin ที่ไม่มี CORS ลง canvas ไม่ได้)
  const pageHtmls=[];
  for(let i=0;i<seq.length;i++){
    const item=seq[i],n=i+1,e=item.e;
    showPdfGenOverlay(true,`กำลังโหลดรูปภาพ... ${n}/${totalPages}`);
    const rawSlots=[[e.thumbMain||e.imgMain,'รูปรวมอุปกรณ์'],[e.thumbSticker||e.imgSticker,'รูปสติกเกอร์'],[e.thumb3||e.img3,'รูปเพิ่มเติมที่ 1'],[e.thumb4||e.img4,'รูปเพิ่มเติมที่ 2']].filter(s=>s[0]);
    const slots=[];
    for(const s of rawSlots){const dataUrl=await fetchImageDataUrl(s[0]); if(dataUrl)slots.push([dataUrl,s[1]]);}
    const hasImg=!!slots.length;
    const body=`<div class="rpt-equip${hasImg?'':' noimg'}"><div class="rpt-equip-title">${n}. ${esc(e.equipment||'(ไม่ระบุ)')}</div>${e.brand?`<div class="rpt-equip-line">ยี่ห้อ ${esc(e.brand)} รุ่น ${esc(e.model||'-')}</div>`:''}${e.serial?`<div class="rpt-equip-meta">Serial: ${esc(e.serial)}</div>`:''}<div class="rpt-equip-loc">${esc(e.locName||'')}${e.subName?' '+esc(e.subName):''}</div>${hasImg?`<div class="rpt-imgs">${slots.map(s=>cell(s[0],s[1])).join('')}</div>`:''}${e.note?`<div class="rpt-note">หมายเหตุ: ${esc(e.note)}</div>`:''}</div>`;
    const footerHtml=`<div class="rpt-runfoot">${n} of ${totalPages}</div>`;
    pageHtmls.push(`<div class="pdf-page">${headerHtml}${item.heading}${body}${footerHtml}</div>`);
  }
  const pagesHtml=pageHtmls.join('');

  showPdfGenOverlay(true,'กำลังสร้าง PDF...');
  const area=$('#reportArea');
  area.innerHTML=pagesHtml;
  const imgs=Array.from(area.querySelectorAll('img'));
  const exportPdf=async()=>{
    showPdfGenOverlay(true,'กำลังสร้าง PDF...');
    area.classList.add('pdf-render');
    // ต้องรอฟอนต์ไทย (IBM Plex Sans Thai) โหลดเสร็จก่อน ไม่งั้นบนมือถือที่เน็ต/CPU ช้ากว่า เครื่องอาจ capture
    // ตอนยังใช้ font fallback อยู่ แล้วพอฟอนต์โหลดเสร็จเกิด reflow เลื่อนตำแหน่งข้อความ ทำให้ข้อความลงไปกองด้านล่าง
    if(document.fonts&&document.fonts.ready) await document.fonts.ready;
    // ต้องรอให้ browser layout จริงก่อน ไม่งั้น html2canvas จะ capture ก่อน reflow เสร็จ ได้ภาพเปล่า
    await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));
    const fn=`รายงานอุปกรณ์_${fileStamp(Date.now())}.pdf`;
    try{
      await html2pdf().set({
        margin:0,
        filename:fn,
        image:{type:'jpeg',quality:0.92},
        // windowWidth คงที่ 794px (=210mm ที่ 96dpi) ไม่ใช้ scrollWidth/scrollHeight (ลองแล้วพังบนคอม)
        // กันปัญหาจอมือถือแคบกว่า .pdf-page มาก ทำให้ html2canvas render ผิดสัดส่วนจนเนื้อหาขยับลงไปกองด้านล่าง
        html2canvas:{scale:2,useCORS:true,windowWidth:794},
        jsPDF:{unit:'mm',format:'a4',orientation:'portrait'},
        pagebreak:{mode:['css']}
      }).from(area).save();
      area.classList.remove('pdf-render');
      showPdfGenOverlayDone();
      await new Promise(r=>setTimeout(r,900));
      showPdfGenOverlay(false);
      toast('สร้าง PDF แล้ว',true);
    }catch(e){
      area.classList.remove('pdf-render');
      showPdfGenOverlay(false);
      toast('สร้าง PDF ไม่สำเร็จ',false);
    }
  };
  if(!imgs.length){exportPdf();return;}
  let done=0,exported=false;
  const tryExport=()=>{if(exported)return;exported=true;exportPdf();};
  const tick=()=>{done++;if(done>=imgs.length)tryExport();};
  imgs.forEach(im=>{if(im.complete){tick();}else{im.addEventListener('load',tick);im.addEventListener('error',tick);}});
  setTimeout(tryExport,8000);
}
