let usersCache=[];
async function loadUsers(){if(!canSeeUsers())return;const r=await api(ACT.listUsers,{});if(r&&r.ok&&Array.isArray(r.users)){usersCache=r.users;renderUsers(r.users);}}
function renderUsers(list){
  list=list||usersCache;window._userList=list;
  const projectOptions=uniq([...master.map(m=>m.project),...list.map(x=>x.project)]).filter(Boolean);
  const nuDl=$('#nuProjectList'); if(nuDl) nuDl.innerHTML=projectOptions.map(p=>`<option value="${escAttr(p)}">`).join('');
  const tb=$('#usersBody');if(!tb)return;
  const projCell=u=>{
    const ps=(u.project||'').split(',').map(p=>p.trim()).filter(Boolean);
    if(!ps.length)return '-';
    return `<select class="proj-select">${ps.map(p=>`<option>${esc(p)}</option>`).join('')}</select>`;
  };
  tb.innerHTML=list.map(u=>`<tr><td><b>${esc(u.username)}</b></td><td class="codecell" style="font-size:12px">${u.username!=='admin'?(u.plainPwd?esc(u.plainPwd):'—'):'••••••••'}</td><td>${esc(u.name||'-')}</td><td><span class="role-badge role-${esc(u.role)}">${esc(u.role)}</span></td><td>${projCell(u)}</td><td><span class="status-dot ${u.active?'active':'inactive'}"></span>${u.active?'ใช้งาน':'ปิดแล้ว'}</td><td>${u.username!=='admin'?`<div class="rowact"><button class="icon-btn" onclick="openEditUser('${u.username}')">✎</button><button class="icon-btn del" onclick="deleteUser('${u.username}')">🗑</button></div>`:'—'}</td></tr>`).join('');
}
// chip UI ใช้ร่วมกันระหว่างฟอร์ม "เพิ่มผู้ใช้" และ "แก้ไขผู้ใช้" — arr ถูก mutate ตรงๆ (อ้างอิงตัวแปรเดิม)
function renderChips(containerId,arr){
  const box=$('#'+containerId); if(!box) return;
  box.innerHTML=arr.map((p,i)=>`<span class="chip">${esc(p)}<span class="chip-x" data-i="${i}">×</span></span>`).join('');
  box.querySelectorAll('.chip-x').forEach(x=>{
    x.onclick=()=>{ arr.splice(parseInt(x.dataset.i,10),1); renderChips(containerId,arr); };
  });
}
