// นำเข้าผู้ใช้หลายคนจาก Excel — username ซ้ำของเดิมจะข้ามไปอัตโนมัติ (ไม่ทับรหัสผ่านเดิม)
if($('#fileUsers'))$('#fileUsers').addEventListener('change',async(ev)=>{
  const file=ev.target.files[0]; if(!file)return;
  const msg=$('#usersImportMsg');
  try{
    const buf=await file.arrayBuffer();
    const wb=XLSX.read(buf,{type:'array'});
    const ws=wb.Sheets[wb.SheetNames[0]];
    const rowsAoa=XLSX.utils.sheet_to_json(ws,{header:1});
    const header=rowsAoa[0]||[];
    const cols=['username','password','name','role','project'];
    const colIdx={};cols.forEach(key=>{const idx=header.findIndex(h=>String(h).replace(/^﻿/,'').trim()===key);if(idx>=0)colIdx[key]=idx;});
    const rows=rowsAoa.slice(1).filter(r=>r&&r.length).map(r=>{
      const obj={};cols.forEach(key=>{if(colIdx[key]!==undefined)obj[key]=String(r[colIdx[key]]||'').trim();});
      return obj;
    }).filter(o=>o.username&&o.password);
    if(!rows.length){if(msg)msg.innerHTML=`<div class="empty">ไม่พบข้อมูลที่นำเข้าได้ (ต้องมีคอลัมน์ username และ password)</div>`;return;}
    const r=await api('bulkCreateUsers',{rows});
    if(r&&r.ok){
      if(msg)msg.innerHTML=`<div class="empty" style="color:var(--ok)">เพิ่มผู้ใช้แล้ว ${r.created} คน${r.skipped?` (ข้าม ${r.skipped} คนที่ username ซ้ำ)`:''}</div>`;
      toast(`เพิ่มผู้ใช้แล้ว ${r.created} คน`,true);
      await loadUsers();
    }else{
      if(msg)msg.innerHTML=`<div class="empty">นำเข้าไม่สำเร็จ</div>`;
      toast((r&&r.message)||'นำเข้าไม่สำเร็จ',false);
    }
  }catch(e){
    if(msg)msg.innerHTML=`<div class="empty">อ่านไฟล์ไม่สำเร็จ</div>`;
    toast('อ่านไฟล์ไม่สำเร็จ',false);
  }
  ev.target.value='';
});

