async function initAuth(){
  $('#authBtn').addEventListener('click',doLogin);
  $('#authPass').addEventListener('keydown',e=>{if(e.key==='Enter')doLogin();});
  $('#authUser').addEventListener('keydown',e=>{if(e.key==='Enter')$('#authPass').focus();});
  $('#authEye').addEventListener('click',()=>{const p=$('#authPass');const show=p.type==='password';p.type=show?'text':'password';$('#authEye').textContent=show?'ซ่อน':'แสดง';});
  $('#logoutBtn').addEventListener('click',()=>{confirmDlg('ออกจากระบบ?','ออกจากระบบ',()=>doLogout());});
  $('#pdpaAccept').addEventListener('click',acceptPdpa);
  const tgl=()=>$('#pdpaBanner').classList.toggle('expanded');
  $('#pdpaDetailBtn').addEventListener('click',tgl);
  $('#pdpaToggle').addEventListener('click',tgl);
  if(loadSession()){
    paintUser();hideGate();
    const v=await api(ACT.verifyToken,{});
    if(v&&v.ok){
      // อัปเดตสิทธิ์ผู้ใช้ให้เป็นปัจจุบันเสมอ (เผื่อ admin เปลี่ยนสิทธิ์ระหว่างที่ session ยังไม่หมดอายุ)
      if(v.user){ saveSession(AUTH.token,v.user); paintUser(); }
      await afterLogin();
    }else doLogout();
  }else showGate();
}
